<?php
/**
 * Account emails in the World Students design, sent from our own server instead of Firebase's default template.
 *
 * POST JSON {type: "verify" | "change" | "reset", email?, newEmail?}
 *   verify  - Authorization: Bearer <ID token>; sends the confirmation link to the token's email
 *   change  - Authorization: Bearer <ID token>; {newEmail}; sends a "confirm the new address" link to newEmail
 *   reset   - {email}; sends a password-reset link (always answers ok, so addresses cannot be probed)
 * The link (oobCode) is generated by Firebase (Admin API, returnOobLink) and leads to https://ntu.dp.ua/auth-action.html.
 * GET ?check=1 - whether the service is configured (no secrets).
 * 503 NOT_CONFIGURED -> the browser falls back to Firebase's own email (see sendOob() in auth.js).
 */
declare(strict_types=1);

require __DIR__ . '/lib/firebase.php';
require __DIR__ . '/lib/mail-template.php';
require __DIR__ . '/lib/mailer.php';

api_headers();

$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';
if ($method === 'OPTIONS') out(204, []);
if ($method === 'GET' && isset($_GET['check'])) out(200, ['ok' => true, 'configured' => fb_sa() !== null, 'mail' => function_exists('mail')]);
if ($method === 'GET' && isset($_GET['preview'])) {
    // sample letter with a dummy link - lets the design be checked in a browser
    header('Content-Type: text/html; charset=utf-8');
    header('X-Robots-Tag: noindex');
    echo mail_render([
        'greeting' => 'Вітаємо, Студенте!',
        'title' => 'Підтвердіть свою пошту',
        'intro' => 'Ви зареєструвалися на студентській платформі World Students НТУ «Дніпровська політехніка». Натисніть кнопку нижче, щоб підтвердити адресу student@example.com - після цього відкриються чат, особисті повідомлення, відгуки й обмін файлами.',
        'button' => 'Підтвердити пошту',
        'url' => SITE . '/auth-action.html?mode=verifyEmail&oobCode=PREVIEW&lang=uk',
        'note' => 'Посилання одноразове й діє обмежений час. Ми ніколи не просимо пароль у листах. Якщо ви не робили цього запиту, просто проігноруйте лист - з вашим акаунтом нічого не станеться.',
    ])[0];
    exit;
}
if ($method !== 'POST') out(405, ['error' => 'METHOD']);
if (fb_sa() === null || !function_exists('mail')) out(503, ['error' => 'NOT_CONFIGURED']);

$in = json_decode((string)file_get_contents('php://input'), true);
if (!is_array($in)) out(400, ['error' => 'BAD_REQUEST']);
$type = (string)($in['type'] ?? '');
$ip = $_SERVER['REMOTE_ADDR'] ?? '0';
if (limited('ip:' . $ip, 30, 86400)) out(429, ['error' => 'TOO_MANY_ATTEMPTS']);

$link = fn(string $mode, string $code) => SITE . '/auth-action.html?mode=' . $mode . '&oobCode=' . rawurlencode($code) . '&lang=uk';
$safety = 'Ми ніколи не просимо пароль у листах. Якщо ви не робили цього запиту, просто проігноруйте лист - з вашим акаунтом нічого не станеться.';

if ($type === 'verify' || $type === 'change') {
    $jwt = fb_bearer();
    $user = $jwt ? fb_verify_id_token($jwt) : null;
    if (!$user || empty($user['email'])) out(401, ['error' => 'TOKEN']);
    $uid = (string)$user['sub'];
    $name = fb_user_name($uid);
    $hello = $name !== '' ? 'Вітаємо, ' . $name . '!' : 'Вітаємо!';

    if ($type === 'verify') {
        if (!empty($user['email_verified'])) out(200, ['ok' => true, 'already' => true]);
        if (limited('uid:' . $uid, 1, 60) || limited('uidday:' . $uid, 6, 86400)) out(429, ['error' => 'TOO_MANY_ATTEMPTS']);
        [$code, $err] = fb_oob_link(['requestType' => 'VERIFY_EMAIL', 'email' => $user['email']]);
        if (!$code) out($err === 'NOT_CONFIGURED' ? 503 : 502, ['error' => $err]);
        $ok = send_mail((string)$user['email'], 'Підтвердіть пошту для World Students', mail_render([
            'greeting' => $hello,
            'title' => 'Підтвердіть свою пошту',
            'intro' => 'Ви зареєструвалися на студентській платформі World Students НТУ «Дніпровська політехніка». Натисніть кнопку нижче, щоб підтвердити адресу ' . $user['email'] . ' - після цього відкриються чат, особисті повідомлення, відгуки й обмін файлами.',
            'button' => 'Підтвердити пошту',
            'url' => $link('verifyEmail', $code),
            'note' => 'Посилання одноразове й діє обмежений час. ' . $safety,
            'preheader' => 'Один клік - і всі можливості платформи відкриті.',
        ]));
        out($ok ? 200 : 502, $ok ? ['ok' => true] : ['error' => 'MAIL']);
    }

    $newEmail = strtolower(trim((string)($in['newEmail'] ?? '')));
    if (!valid_email($newEmail)) out(400, ['error' => 'INVALID_EMAIL']);
    if (limited('uid:' . $uid, 1, 60) || limited('uidday:' . $uid, 6, 86400)) out(429, ['error' => 'TOO_MANY_ATTEMPTS']);
    [$code, $err] = fb_oob_link(['requestType' => 'VERIFY_AND_CHANGE_EMAIL', 'idToken' => $jwt, 'newEmail' => $newEmail]);
    if (!$code) out($err === 'EMAIL_EXISTS' ? 400 : ($err === 'NOT_CONFIGURED' ? 503 : 502), ['error' => $err]);
    $ok = send_mail($newEmail, 'Підтвердіть нову пошту для World Students', mail_render([
        'greeting' => $hello,
        'title' => 'Підтвердіть нову адресу',
        'intro' => 'Ви хочете змінити пошту свого акаунта World Students на ' . $newEmail . '. Натисніть кнопку, щоб підтвердити зміну - після цього входьте вже з новою адресою.',
        'button' => 'Підтвердити нову пошту',
        'url' => $link('verifyAndChangeEmail', $code),
        'note' => 'Поки ви не натиснете кнопку, акаунт залишається прив’язаним до старої адреси. ' . $safety,
        'preheader' => 'Підтвердіть зміну пошти акаунта.',
    ]));
    out($ok ? 200 : 502, $ok ? ['ok' => true] : ['error' => 'MAIL']);
}

if ($type === 'reset') {
    $email = strtolower(trim((string)($in['email'] ?? '')));
    if (!valid_email($email)) out(400, ['error' => 'INVALID_EMAIL']);
    // the same answer whether or not the account exists
    if (limited('reset:' . $email, 1, 60) || limited('resetday:' . $email, 5, 86400)) out(200, ['ok' => true]);
    [$code, $err] = fb_oob_link(['requestType' => 'PASSWORD_RESET', 'email' => $email]);
    if (!$code) {
        if ($err === 'NOT_CONFIGURED') out(503, ['error' => $err]);
        out(200, ['ok' => true]);
    }
    send_mail($email, 'Новий пароль для World Students', mail_render([
        'title' => 'Встановіть новий пароль',
        'intro' => 'Ми отримали запит на відновлення доступу до акаунта World Students з адресою ' . $email . '. Натисніть кнопку, щоб придумати новий пароль.',
        'button' => 'Встановити новий пароль',
        'url' => $link('resetPassword', $code),
        'note' => 'Посилання діє обмежений час, а старий пароль працює, доки ви не задасте новий. ' . $safety,
        'preheader' => 'Відновлення доступу до акаунта.',
    ]));
    out(200, ['ok' => true]);
}

out(400, ['error' => 'TYPE']);
